import struct
import typing
import asyncio

from jsilib import _utils
from jsilib.base import IClosable
from jsilib.aio import helpers as aio_helpers
from jsilib.transport.frames import Chunk, Ack, Nack

from . import _utils as _jsi_utils, exc as jsi_exc
from .interface import IJSIMessage


class JSISwimOutgoingMessage(IClosable):
    """Outgoing message for SWIM compatibility mode connection.

    :param header:
        The header to be sent.

    :param message:
        The message to be sent.

        It is assumed, that first 4 bytes of the message is the length of the
        JSON header, as SWIM does not have proper protocol layering. To avoid
        overflow, it is required that the message is always prefixed with
        additional 4 zeroed bytes if non-JSONRPC message is sent. For JSONRPC
        messages, first 4 bytes will always be the header size. Later, the
        header is always added to each sent chunk.

    :param chunk_size:
        Maximum size of single chunk, in bytes.

        Must be >= 5.
    """

    def __init__(self, header: bytes, body: IJSIMessage, chunk_size: int):
        self._header = header
        self._body = body
        self._chunk_size = chunk_size
        self._chunks_left = _jsi_utils.calc_number_of_outgoing_chunks_for_swim(len(header), body.bytes_left(), chunk_size)
        self._real_message_size = body.bytes_left() + self._chunks_left * (len(header) + 4)
        self._message_id = _utils.next_unique_id(self.__class__, start=0, step=2)
        self._index = 0
        self._closed = False
        self._ack_nack_sem = asyncio.Semaphore(0)
        self._ack_or_nack = None
        self._pending_chunk = None

    @property
    def id(self):
        return self._message_id

    def is_closed(self) -> bool:
        return self._closed

    async def close(self):
        if not self._closed:
            self._closed = True
            await self._body.close()
            self._ack_or_nack = None
            self._ack_nack_sem.release()

    def dispatch_ack_or_nack(self, ack_or_nack: typing.Union[Ack, Nack]):
        """Dispatch received ACK or NACK.

        Calling this unlocks :meth:`receive_ack_or_nack`, which is then
        performing needed validation.
        """
        self._ack_or_nack = ack_or_nack
        self._ack_nack_sem.release()

    async def receive_ack_or_nack(self) -> typing.Optional[typing.Union[Ack, Nack]]:
        """Block until :meth:`dispatch_ack_or_nack` is called.

        Once ACK or NACK is received, the method performs validation of
        received frame and raises exception if received ACK/NACK does not match
        pending chunk.
        """
        if self._pending_chunk is None:
            raise jsi_exc.ProtocolError("no pending chunk found")
        await self._ack_nack_sem.acquire()
        chunk = self._pending_chunk
        ack_or_nack = self._ack_or_nack
        if ack_or_nack is None:
            return None
        if chunk.message_id != ack_or_nack.message_id:
            raise jsi_exc.ProtocolError(f"got ACK or NACK with wrong message ID: {ack_or_nack}")
        if chunk.index != ack_or_nack.index:
            raise jsi_exc.ProtocolError(f"got ACK or NACK with wrong index: {ack_or_nack}")
        if isinstance(ack_or_nack, Nack):
            await self.close()
            raise jsi_exc.TransferRejectedError()
        self._pending_chunk = None
        return ack_or_nack

    async def next_chunk(self) -> typing.Optional[Chunk]:
        """Return next CHUNK frame or ``None`` if there are no more chunks."""
        if self._pending_chunk is not None:
            raise jsi_exc.ProtocolError(f"still waiting for ACK/NACK for: {self._pending_chunk}")
        if self._chunks_left == 0:
            return None
        payload = struct.pack("!I", len(self._header)) + self._header
        assert self._chunk_size > len(payload)
        read_count = min(self._body.bytes_left(), self._chunk_size - len(payload))
        payload += await aio_helpers.read_all(self._body, read_count)
        self._pending_chunk = chunk_frame = Chunk(self._message_id, self._index, self._real_message_size, payload)
        self._index += 1
        self._chunks_left -= 1
        return chunk_frame
